from pathlib import Path
import shutil,datetime,base64
p=Path('/opt/kiwoom/dashboard-source/dist/index.html');s=p.read_text()
assert 'id="real-operation-status-module"' not in s
assert 'function updateHoldings(items)' in s
suffix='.before-real-operation-status-'+datetime.datetime.now().strftime('%Y%m%d%H%M%S')
shutil.copy2(p,str(p)+suffix)
block=base64.b64decode('').decode()
new=s.replace('</body>',block+'</body>')
assert new!=s
tmp=p.with_suffix('.tmp');tmp.write_text(new);tmp.chmod(p.stat().st_mode);tmp.replace(p)
print('REAL_OPERATION_STATUS_UPDATED',suffix)
